solution:
fn validate_http_method(method: Str) -> Str {
  panic_if(method.len() == 0, "HTTP method cannot be empty");
  panic_if(method != "GET" && method != "POST" && method != "PUT" && method != "DELETE",
    "unsupported HTTP method: '" + method + "' — use GET, POST, PUT, or DELETE");
  return method;
}

fn main() -> Int {
  let m = validate_http_method("GET");
  return m.len();
}
